def _convert(field):
    if field == "":
        return None
    if _INT_RE.fullmatch(field):
        return int(field)
    if _FLOAT_RE.fullmatch(field):
        return float(field)
    return field


def _read_table(name, directory):
    if not name or "/" in name or "\\" in name or name in (".", ".."):
        raise QueryError(f"invalid table name: {name!r}")
    path = os.path.join(directory, name + ".csv")
    if not os.path.isfile(path):
        raise QueryError(f"no such table: {name}")
    try:
        with open(path, newline="", encoding="utf-8-sig") as f:
            reader = csv.reader(f)
            header = next(reader, None)
            if header is None:
                raise QueryError(f"table {name} has no header line")
            width = len(header)
            rows = []
            for line_no, fields in enumerate(reader, start=2):
                if not fields:
                    continue  # blank line
                if len(fields) > width:
                    raise QueryError(
                        f"{name}.csv line {line_no}: {len(fields)} fields, "
                        f"header has {width}")
                values = [_convert(x) for x in fields]
                values.extend([None] * (width - len(values)))
                rows.append(tuple(values))
    except (OSError, UnicodeDecodeError, csv.Error) as e:
        raise QueryError(f"cannot read table {name}: {e}") from None
    return header, rows


# ---------------------------------------------------------------- values

def _category(v):
    if v is None:
        return None
    if isinstance(v, bool):
        return "boolean"
    if isinstance(v, (int, float)):
        return "number"
    if isinstance(v, str):
        return "text"
    raise QueryError(f"unsupported value: {v!r}")  # pragma: no cover


def _value_key(v):
    """Hashable key for value equality (GROUP BY, DISTINCT): booleans never
    equal numbers; 1 and 1.0 are equal."""
